//! 🏃️ Shaped multiline outline runs match rustybuzz and ttf-parser placement and pixels and retain completed children through funded close.
use super::*;
use semio_framework_2d_text_font::*;
use semio_framework_2d_text_font_testing::{bytes,close};
#[global_allocator]
static FONT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn shape_features()->[rustybuzz::Feature;3]{[b"liga",b"clig",b"calt"].map(|tag|rustybuzz::Feature{tag:ttf_parser::Tag::from_bytes(tag),value:0,start:0,end:u32::MAX})}
struct OracleRunPath<'a>{path:&'a mut tiny_skia::PathBuilder,origin:[f64;2],scale:f64}
impl OracleRunPath<'_>{fn map(&self,x:f32,y:f32)->[f32;2]{[(self.origin[0]+f64::from(x)*self.scale)as f32,(self.origin[1]-f64::from(y)*self.scale)as f32]}}
impl ttf_parser::OutlineBuilder for OracleRunPath<'_>{fn move_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.move_to(p[0],p[1]);}fn line_to(&mut self,x:f32,y:f32){let p=self.map(x,y);self.path.line_to(p[0],p[1]);}fn quad_to(&mut self,x1:f32,y1:f32,x:f32,y:f32){let a=self.map(x1,y1);let b=self.map(x,y);self.path.quad_to(a[0],a[1],b[0],b[1]);}fn curve_to(&mut self,x1:f32,y1:f32,x2:f32,y2:f32,x:f32,y:f32){let a=self.map(x1,y1);let b=self.map(x2,y2);let c=self.map(x,y);self.path.cubic_to(a[0],a[1],b[0],b[1],c[0],c[1]);}fn close(&mut self){self.path.close();}}
fn path_from_segments(segments:&PagedList<semio_framework_2d_engine::PathSegment,{usize::MAX}>)->Option<tiny_skia::Path>{let mut path=tiny_skia::PathBuilder::new();for segment in segments.iter(){match segment{semio_framework_2d_engine::PathSegment::Move{to}=>path.move_to(to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Line{to}=>path.line_to(to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Quad{ctrl,to}=>path.quad_to(ctrl[0]as f32,ctrl[1]as f32,to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Close=>path.close(),_=>panic!("Unexpected glyph curve")}}path.finish()}
fn rendered_run(path:Option<tiny_skia::Path>)->tiny_skia::Pixmap{let mut image=tiny_skia::Pixmap::new(512,256).unwrap();if let Some(path)=path{image.fill_path(&path,&tiny_skia::Paint::default(),tiny_skia::FillRule::Winding,tiny_skia::Transform::from_translate(8.0,8.0),None);}image}
#[test]
fn font_run_original_shaped_cluster_outlines(){use semio_framework_2d_text_font_shape_unicode::*;let mut rows:serde_json::Value=serde_json::from_str(include_str!("../../🧵️shape/🧵️layout/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let run_rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();rows.as_array_mut().unwrap().extend(run_rows.as_array().unwrap().iter().cloned());let mut unicode_admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let data=unicode_admission.take_result().unwrap();for row in rows.as_array().unwrap(){let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let font=admission.take_result().unwrap();let text=row["text"].as_str().unwrap();let oracle_text=row["oracleText"].as_str().unwrap_or(text);let source_offset=text.find(oracle_text).unwrap();let mut buffer=rustybuzz::UnicodeBuffer::new();for(at,scalar)in oracle_text.char_indices(){buffer.add(scalar,(source_offset+at)as u32);}buffer.guess_segment_properties();if row["oracleDirection"].as_str()==Some("rtl"){buffer.set_direction(rustybuzz::Direction::RightToLeft);}let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);let style=crate::FontRunStyle{size:40.0,origin:[8.0,8.0],line_height:1.2,kerning:true,outlines:true};for grant in [1,7,4096]{let mut cursor=crate::FontOutlineRunCursor::new(text,1,style,FontOutlineLimits::default(),data.layout,&data.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);let mut work=0;loop{let p=cursor.advance(text,std::slice::from_ref(&font),&data.source,&[],grant,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(grant))).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();let ignore=row["ignorableGlyphs"].as_array();let visible=oracle.glyph_infos().iter().zip(oracle.glyph_positions()).filter(|(glyph,_)|!ignore.is_some_and(|values|values.iter().any(|value|value.as_u64()==Some(u64::from(glyph.glyph_id))))).collect::<Vec<_>>();assert_eq!(output.glyphs.len(),visible.len());if let Some(glyphs)=row["glyphs"].as_array(){assert_eq!(visible.iter().map(|(glyph,_)|u64::from(glyph.glyph_id)).collect::<Vec<_>>(),glyphs.iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());}if let Some(positions)=row["positions"].as_array(){assert_eq!(visible.iter().map(|(_,position)|[i64::from(position.x_advance),i64::from(position.x_offset),i64::from(position.y_offset)]).collect::<Vec<_>>(),positions.iter().map(|value|[value[0].as_i64().unwrap(),value[1].as_i64().unwrap(),value[2].as_i64().unwrap()]).collect::<Vec<_>>());}let scale=style.size/f64::from(font.face.units_per_em);let mut pen=0.0;for(actual,(glyph,position))in output.glyphs.iter().zip(visible){assert_eq!(actual.glyph,u16::try_from(glyph.glyph_id).unwrap());assert_eq!(actual.source_at,glyph.cluster as usize);assert!((actual.origin[0]-(style.origin[0]+pen+f64::from(position.x_offset)*scale)).abs()<1e-9);assert!((actual.origin[1]-(style.origin[1]+style.size-f64::from(position.y_offset)*scale)).abs()<1e-9);pen+=f64::from(position.x_advance)*scale;}assert!((output.advance-pen).abs()<1e-9);close(cursor);close(output);}for stop in [0,1,2,7,100,1000,10000]{let mut cursor=crate::FontOutlineRunCursor::new(text,1,style,FontOutlineLimits::default(),data.layout,&data.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);if stop>0{cursor.advance(text,std::slice::from_ref(&font),&data.source,&[],stop,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(stop))).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}close(admission);close(font);}close(unicode_admission);close(data);}
#[test]
fn font_run_shared_multiline_outlines_match_rustybuzz_ttf_parser(){let mut unicode_admission=semio_framework_2d_text_font_shape_unicode::UnicodeDataAdmissionJob::new(semio_framework_2d_text_font_shape_unicode::UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let unicode=unicode_admission.take_result().unwrap();let rows:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let text=row["text"].as_str().unwrap().to_string();let text_pointer=text.as_ptr();let style=crate::FontRunStyle{size:row["size"].as_f64().unwrap(),origin:[row["origin"][0].as_f64().unwrap(),row["origin"][1].as_f64().unwrap()],line_height:1.2,kerning:true,outlines:true};let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(7,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(7))).unwrap().done{}let fonts=[admission.take_result().unwrap()];let font_pointer=fonts[0].source.as_ptr();let parser=ttf_parser::Face::parse(&fonts[0].source,0).unwrap();let shaper=rustybuzz::Face::from_slice(&fonts[0].source,0).unwrap();let scale=style.size/f64::from(fonts[0].face.units_per_em);let mut paths=tiny_skia::PathBuilder::new();let normalized=text.replace("\r\n","\n").replace('\r',"\n");let mut expected=Vec::<(u16,[f64;2])>::new();let mut advance=0.0f64;for(line,content)in normalized.split('\n').enumerate(){let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(content);buffer.guess_segment_properties();let shaped=rustybuzz::shape(&shaper,&shape_features(),buffer);let mut x=style.origin[0];let y=style.origin[1]+style.size+line as f64*style.size*style.line_height;for(info,position)in shaped.glyph_infos().iter().zip(shaped.glyph_positions()){let origin=[x+f64::from(position.x_offset)*scale,y-f64::from(position.y_offset)*scale];expected.push((info.glyph_id as u16,origin));let mut path=OracleRunPath{path:&mut paths,origin,scale};parser.outline_glyph(ttf_parser::GlyphId(info.glyph_id as u16),&mut path);x+=f64::from(position.x_advance)*scale;}advance=advance.max(x-style.origin[0]);}let reference=rendered_run(paths.finish());let mut cursor=crate::FontOutlineRunCursor::new(&text,fonts.len(),style,FontOutlineLimits::default(),unicode.layout,&unicode.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);let mut work=0;loop{let p=cursor.advance(&text,&fonts,&unicode.source,&[],grant,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(grant))).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();assert_eq!(output.lines,row["expectedLines"].as_u64().unwrap()as usize);assert!((output.advance-advance).abs()<1e-8);assert_eq!(output.glyphs.len(),expected.len());for(glyph,(id,origin))in output.glyphs.iter().zip(expected){assert_eq!(glyph.glyph,id);assert!((glyph.origin[0]-origin[0]).abs()<1e-8,"{} grant={grant} glyph={id}",row["name"]);assert!((glyph.origin[1]-origin[1]).abs()<1e-8);}let actual=rendered_run(path_from_segments(&output.segments));assert!(actual.data().iter().zip(reference.data()).all(|(a,b)|a.abs_diff(*b)<=1),"{} grant={grant}",row["name"]);assert_eq!(text.as_ptr(),text_pointer);assert_eq!(fonts[0].source.as_ptr(),font_pointer);close(cursor);close(output);close(admission);let [font]=fonts;close(font);close(text);}}close(unicode_admission);close(unicode);}
#[test]
fn font_run_cancellation_retains_actual_completed_children(){let mut unicode_admission=semio_framework_2d_text_font_shape_unicode::UnicodeDataAdmissionJob::new(semio_framework_2d_text_font_shape_unicode::UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let unicode=unicode_admission.take_result().unwrap();let text="Grüße AV To".to_string();let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(7,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(7))).unwrap().done{}let fonts=[admission.take_result().unwrap()];let style=crate::FontRunStyle{size:24.0,origin:[0.0;2],line_height:1.2,kerning:true,outlines:true};for stop in [0,1,2,7,20,100,1000,10000]{let mut cursor=crate::FontOutlineRunCursor::new(&text,1,style,FontOutlineLimits::default(),unicode.layout,&unicode.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);if stop>0{cursor.advance(&text,&fonts,&unicode.source,&[],stop,&mut semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(stop))).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}let missing="\u{10ffff}";let mut cursor=crate::FontOutlineRunCursor::new(missing,1,style,FontOutlineLimits::default(),unicode.layout,&unicode.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);assert!(cursor.advance(missing,&fonts,&unicode.source,&[],10000).is_err());close(cursor);close(admission);let [font]=fonts;close(font);close(text);close(unicode_admission);close(unicode);}

